import logo from './logo.svg';
import './App.css';

const App = () => {
  const [cart, setCart] = useState([]);
  const [showPopup, setShowPopup] = useState(false);

  const products = [
    { id: 1, name: 'Almonds', price: 500, image: 'https://via.placeholder.com/150' },
    { id: 2, name: 'Cashews', price: 600, image: 'https://via.placeholder.com/150' },
    { id: 3, name: 'Walnuts', price: 700, image: 'https://via.placeholder.com/150' },
    { id: 4, name: 'Dates', price: 400, image: 'https://via.placeholder.com/150' },
  ];

  const addToCart = (product) => {
    setCart([...cart, product]);
  };

  const removeFromCart = (id) => {
    setCart(cart.filter(item => item.id !== id));
  };

  const handlePayNow = () => {
    setShowPopup(true);
  };

  const closePopup = () => {
    setShowPopup(false);
  };

  return (
    <div style={{ fontFamily: 'Arial, sans-serif', padding: '20px' }}>
      <h1>Dry Fruits Shop</h1>
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: '20px' }}>
        {products.map(product => (
          <div key={product.id} style={{ border: '1px solid #ccc', padding: '10px', width: '200px' }}>
            <img src={product.image} alt={product.name} style={{ width: '100%', height: '150px', objectFit: 'cover' }} />
            <h3>{product.name}</h3>
            <p>₹{product.price}</p>
            <button onClick={() => addToCart(product)}>Add to Cart</button>
          </div>
        ))}
      </div>

      <h2>Cart</h2>
      <ul>
        {cart.map(item => (
          <li key={item.id}>
            {item.name} - ₹{item.price}
            <button onClick={() => removeFromCart(item.id)} style={{ marginLeft: '10px' }}>Remove</button>
          </li>
        ))}
      </ul>

      <button onClick={handlePayNow} style={{ marginTop: '20px', padding: '10px 20px', fontSize: '16px' }}>
        Pay Now
      </button>

      {showPopup && (
        <div style={{
          position: 'fixed',
          top: '50%',
          left: '50%',
          transform: 'translate(-50%, -50%)',
          backgroundColor: '#fff',
          padding: '20px',
          border: '1px solid #ccc',
          boxShadow: '0 4px 8px rgba(0,0,0,0.2)',
          zIndex: 1000
        }}>
          <h3>Payment Details</h3>
          <p>Please pay to this number: +91 9876543210</p>
          <button onClick={closePopup} style={{ marginTop: '10px' }}>Close</button>
        </div>
      )}
    </div>
  );
};

export default App;
